import React,{useState}from'react';import{useNavigate}from'react-router-dom';
export default function AIPlanner(){const n=useNavigate();const[m,sM]=useState([{text:'Halo Andi! Saya WORKIE AI. Deskripsikan pekerjaan yang kamu butuhkan dengan bahasa santai saja. Nanti saya rapikan jadi draf order siap pakai!',sender:'ai'},{text:'Gue butuh desainer buat bikin logo cafe kopi baru punya temen. Cafe-nya berkonsep minimalis modern.',sender:'user'},{text:'Siap, logo cafe kopi minimalis modern! Biar rancangannya mantap, boleh tahu detail ini?
1. Kapan deadlinenya?
2. Anggarannya berapa?
3. Desainnya digarap Solo atau Team?',sender:'ai'},{text:'Butuh kelar 2 hari lagi sih, budget kisaran 250rb-300rb, cukup kerjain Solo aja.',sender:'user'}]);const[inp,setInp]=useState('');const send=()=>{if(!inp.trim())return;sM([...m,{text:inp,sender:'user'}]);setInp('');setTimeout(()=>sM(p=>[...p,{text:'Siap, saya sudah catat semua detailnya! Klik "Lanjutkan" untuk lihat draf order.',sender:'ai'}]),1000)};return(<div style={{maxWidth:402,margin:'0 auto',background:'#F8F9FA',minHeight:'100vh',padding:'16px 20px 80px'}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}><span style={{fontSize:24,cursor:'pointer'}} onClick={()=>n('/dashboard-customer')}>←</span><h1 style={{fontSize:20,fontWeight:800,color:'#0D9488'}}>WORKIE AI Planner</h1><span>🟢</span></div><p style={{color:'#475569',marginBottom:16}}>Online & Siap Membantu</p><div style={{display:'flex',flexDirection:'column',gap:12,marginBottom:16}}>{m.map((x,i)=><div key={i} style={{maxWidth:'85%',alignSelf:x.sender==='ai'?'flex-start':'flex-end'}}><div style={{padding:'12px 16px',borderRadius:16,background:x.sender==='ai'?'#fff':'#0D9488',color:x.sender==='ai'?'#0F172A':'#fff'}}>{x.text.split('
').map((l,j)=><div key={j}>{l}</div>)}</div><p style={{fontSize:11,color:'#94A3B8',marginTop:4}}>{x.sender==='ai'?'WORKIE AI':'Andi'}</p></div>)}</div><div style={{display:'flex',gap:8,position:'fixed',bottom:80,left:'50%',transform:'translateX(-50%)',maxWidth:402,width:'90%',background:'#fff',padding:8,borderRadius:12,border:'1px solid #E2E8F0'}}><input type="text" placeholder="Ketik balasan Anda disini..." value={inp} onChange={e=>setInp(e.target.value)} onKeyPress={e=>e.key==='Enter'&&send()} style={{flex:1,padding:10,border:'none',outline:'none',fontSize:14}}/><button onClick={send} style={{padding:'8px 16px',background:'#0D9488',color:'#fff',border:'none',borderRadius:8}}>➤</button></div><button onClick={()=>n('/order-detail')} style={{width:'100%',padding:14,background:'#0D9488',color:'#fff',border:'none',borderRadius:12,fontSize:16,fontWeight:700,marginTop:16}}>Lanjutkan ke Order Detail</button></div>)}
